UPDATE ai_chat_session
SET title = #{title}
WHERE workspace_id = #{workspaceId}
  AND id = #{id}
  AND title_user_set = FALSE
  AND (
    SELECT COUNT(*)
    FROM ai_chat_message m
    WHERE m.workspace_id = #{workspaceId}
      AND m.session_id = #{id}
      AND m.author_kind = 'assistant'
  ) = 1

