UPDATE ai_chat_message
SET content = #{content},
    structured_json = #{structuredJson,jdbcType=VARCHAR},
    input_tokens = LEAST(2147483647, COALESCE(input_tokens, 0) + #{inputTokens}),
    output_tokens = LEAST(2147483647, COALESCE(output_tokens, 0) + #{outputTokens})
WHERE workspace_id = #{workspaceId}
  AND session_id = #{sessionId}
  AND id = #{id}
  AND author_kind = 'system'

