UPDATE ai_chat_turn
SET status = #{status}, terminal_reason = #{terminalReason,jdbcType=VARCHAR}
WHERE mission_run_id IS NULL AND workspace_id = #{workspaceId}
  AND session_id = #{sessionId}
  AND id = #{id}
  AND status = #{expectedStatus}
  AND updated_at <=
      DATE_SUB(CURRENT_TIMESTAMP(6), INTERVAL #{lifetimeSeconds} SECOND)

UPDATE ai_chat_turn
SET partial_content = CONCAT(COALESCE(partial_content, ''), #{content}),
    partial_content_utf16_offset = #{nextOffset}
WHERE workspace_id = #{workspaceId}
  AND session_id = #{sessionId}
  AND id = #{id}
  AND status = 'running'
  AND streamed = TRUE
  AND partial_content_utf16_offset = #{expectedOffset}
  AND cancel_requested_at IS NULL

UPDATE ai_chat_turn
SET partial_content = NULL,
    partial_content_utf16_offset = 0
WHERE workspace_id = #{workspaceId}
  AND session_id = #{sessionId}
  AND id = #{id}
  AND status = 'running'
  AND streamed = TRUE
  AND partial_content_utf16_offset = #{expectedOffset}
  AND cancel_requested_at IS NULL

UPDATE ai_chat_turn
SET partial_content = #{content},
    partial_content_utf16_offset = #{offset}
WHERE workspace_id = #{workspaceId}
  AND session_id = #{sessionId}
  AND id = #{id}
  AND status = 'running'
  AND streamed = TRUE
  AND cancel_requested_at IS NULL

UPDATE ai_chat_turn
SET status = 'cancelled',
    terminal_reason = 'cancelled',
    cancel_requested_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND session_id = #{sessionId}
  AND id = #{id}
  AND status IN ('queued', 'running')

mapper.select:
SELECT tc.id, tc.workspace_id, tc.message_id, m.session_id, m.author_user_id AS requested_by_user_id, tc.tool_name, tc.status, tc.arguments_json, tc.thought_signature, tc.result_json, tc.executed_by_user_id, tc.executed_at, tc.idempotency_key, tc.server_proposal, tc.mission_run_id, tc.artifact_origin, tc.privacy_generation, tc.created_at, tc.updated_at FROM ai_chat_tool_call tc JOIN ai_chat_message m ON m.workspace_id = tc.workspace_id AND m.id = tc.message_id WHERE tc.workspace_id = #{workspaceId} AND AND m.session_id = #{sessionId}
AND tc.status = 'proposed' AND tc.server_proposal = TRUE AND tc.created_at > #{reviewCreatedAfter}
ORDER BY m.seq ASC, tc.id ASC LIMIT #{limit}

mapper.update:
UPDATE ai_chat_tool_call
SET status = #{status},
    result_json = #{resultJson,jdbcType=VARCHAR},
    executed_by_user_id = #{executedByUserId},
    executed_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND message_id = #{messageId}
  AND id = #{id}
  AND status = 'proposed'
